#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');
const { execFileSync } = require('node:child_process');

const repoRoot = path.resolve(__dirname, '../../..');
const requestPath = path.join(repoRoot, 'ChatMachines/GeminiSupervisor/live-ground-truth/read-request.json');
const roomPath = path.join(repoRoot, 'ChatMachines/GeminiSupervisor/live-ground-truth/reading-room');
const taskDefinitionPath = path.join(repoRoot, 'ChatMachines/ComprehensionTasks/Tasks/task_semantic_define_each_array_item.json');
const projectionRelativePath = 'ChatMachines/ComprehensionTasks/ProjectionsForTasks/agentsmdbaseproejction.json';
const flattenCheckerPath = path.join(repoRoot, 'ChatMachines/ComprehensionTasks/scripts/check-single-child.js');

const TASK_ID = 'task_semantic_define_each_array_item';
const ACTIVE_RE = new RegExp(`^${TASK_ID}-([0-9a-f]{40})\\.json$`, 'i');
const EXPECTED_EVALS = [
  'definition',
  'semantic_role',
  'referent',
  'relationship_to_parent',
  'semantic_contribution',
  'semantic_class'
];

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
}

function validateCommitSha(value) {
  if (!/^[0-9a-f]{40}$/i.test(value || '')) throw new Error(`Invalid commit SHA: ${value}`);
  return value.toLowerCase();
}

function activePathFor(commitSha) {
  return path.join(roomPath, `${TASK_ID}-${validateCommitSha(commitSha)}.json`);
}

function resultPathFor(commitSha, status) {
  return path.join(roomPath, `${TASK_ID}-${validateCommitSha(commitSha)}-${status}.json`);
}

function removeActiveInstances() {
  if (!fs.existsSync(roomPath)) return;
  for (const name of fs.readdirSync(roomPath)) {
    if (ACTIVE_RE.test(name)) fs.rmSync(path.join(roomPath, name), { force: true });
  }
}

function resolveRepoFile(relativePath) {
  if (typeof relativePath !== 'string' || relativePath.trim() === '') throw new Error('Expected a non-empty repository-relative filename.');
  const resolved = path.resolve(repoRoot, relativePath);
  const prefix = `${repoRoot}${path.sep}`;
  if (resolved !== repoRoot && !resolved.startsWith(prefix)) throw new Error(`Path escapes repository root: ${relativePath}`);
  return resolved;
}

function filePredicates(relativePath) {
  const absolute = resolveRepoFile(relativePath);
  const exists = fs.existsSync(absolute) && fs.statSync(absolute).isFile();
  let parsed = null;
  let raw = '';
  let isJson = false;
  let isMinified = false;
  let isFlattened = false;

  if (exists) {
    raw = fs.readFileSync(absolute, 'utf8');
    try {
      parsed = JSON.parse(raw);
      isJson = true;
      isMinified = raw.trim() === JSON.stringify(parsed);
    } catch {
      isJson = false;
    }
  }

  if (exists && isJson) {
    try {
      const output = execFileSync(process.execPath, [flattenCheckerPath, absolute], { encoding: 'utf8' });
      isFlattened = JSON.parse(output).valid === true;
    } catch {
      isFlattened = false;
    }
  }

  return {
    file_does_exist_$bool: exists,
    file_is_json_$bool: isJson,
    file_is_minified_$bool: isMinified,
    file_is_flattened_$bool: isFlattened,
    parsed
  };
}

function terminalNode(value) {
  let node = value;
  while (node !== null && typeof node === 'object') {
    if (Array.isArray(node)) {
      if (node.length !== 1) return node;
      node = node[0];
      continue;
    }
    const keys = Object.keys(node);
    if (keys.length !== 1) return node;
    node = node[keys[0]];
  }
  return node;
}

function terminalIsEmptyContainer(value) {
  const terminal = terminalNode(value);
  if (Array.isArray(terminal)) return terminal.length === 0;
  return terminal !== null && typeof terminal === 'object' && Object.keys(terminal).length === 0;
}

function expectedNonemptySignatures(array) {
  if (!Array.isArray(array)) throw new Error('Target JSON must be an array.');
  return array.filter(item => !terminalIsEmptyContainer(item)).map(item => JSON.stringify(item));
}

function parseJsonArchive(archiveRelativePath) {
  const absolute = resolveRepoFile(archiveRelativePath);
  if (!fs.existsSync(absolute) || !fs.statSync(absolute).isFile()) throw new Error(`Complete batch archive does not exist: ${archiveRelativePath}`);
  const lower = archiveRelativePath.toLowerCase();
  let text;

  if (lower.endsWith('.zip')) {
    const listing = execFileSync('unzip', ['-Z1', absolute], { encoding: 'utf8' })
      .split(/\r?\n/).filter(Boolean).filter(name => name.toLowerCase().endsWith('.json'));
    if (listing.length !== 1) throw new Error('ZIP solution must contain exactly one JSON file.');
    text = execFileSync('unzip', ['-p', absolute, listing[0]], { encoding: 'utf8', maxBuffer: 100 * 1024 * 1024 });
  } else if (lower.endsWith('.tar.gz') || lower.endsWith('.tgz')) {
    const listing = execFileSync('tar', ['-tzf', absolute], { encoding: 'utf8' })
      .split(/\r?\n/).filter(Boolean).filter(name => name.toLowerCase().endsWith('.json'));
    if (listing.length !== 1) throw new Error('TAR.GZ solution must contain exactly one JSON file.');
    text = execFileSync('tar', ['-xOzf', absolute, listing[0]], { encoding: 'utf8', maxBuffer: 100 * 1024 * 1024 });
  } else if (lower.endsWith('.gz')) {
    text = zlib.gunzipSync(fs.readFileSync(absolute)).toString('utf8');
  } else {
    text = fs.readFileSync(absolute, 'utf8');
  }

  return JSON.parse(text);
}

function validateSemanticEvaluationArray(records, expectedSignatures) {
  if (!Array.isArray(records) || records.length !== expectedSignatures.length) return false;
  for (let i = 0; i < records.length; i++) {
    if (!(i in records)) return false;
    const record = records[i];
    if (record === null || typeof record !== 'object' || Array.isArray(record)) return false;
    const outerKeys = Object.keys(record);
    if (outerKeys.length !== 1 || outerKeys[0] !== expectedSignatures[i]) return false;

    const evaluations = record[outerKeys[0]];
    if (evaluations === null || typeof evaluations !== 'object' || Array.isArray(evaluations)) return false;
    const evalKeys = Object.keys(evaluations);
    if (evalKeys.length !== EXPECTED_EVALS.length) return false;
    for (let j = 0; j < EXPECTED_EVALS.length; j++) {
      if (evalKeys[j] !== EXPECTED_EVALS[j]) return false;
      if (typeof evaluations[evalKeys[j]] !== 'string' || evaluations[evalKeys[j]].trim() === '') return false;
    }
  }
  return true;
}

async function issue(commitSha) {
  const sha = validateCommitSha(commitSha);
  const request = readJson(requestPath);
  if (request['Agents.md'] !== true) throw new Error('read-request.json must contain "Agents.md": true');

  const task = readJson(taskDefinitionPath);
  if (JSON.stringify(task?.doRecord_withReturnSchema?.semantic_evaluations) !== JSON.stringify(EXPECTED_EVALS)) {
    throw new Error('Task semantic_evaluations does not match the verifier evaluation contract.');
  }
  if (!Array.isArray(task.glossary) || task.glossary.length !== EXPECTED_EVALS.length) {
    throw new Error('Task glossary must contain exactly one element for each semantic evaluation type.');
  }
  for (let i = 0; i < EXPECTED_EVALS.length; i++) {
    const glossaryKeys = Object.keys(task.glossary[i] || {});
    if (glossaryKeys.length !== 1 || glossaryKeys[0] !== EXPECTED_EVALS[i]) {
      throw new Error(`Glossary element ${i} must define ${EXPECTED_EVALS[i]}.`);
    }
  }

  const predicates = filePredicates(projectionRelativePath);
  const readiness = [predicates.file_does_exist_$bool, predicates.file_is_json_$bool, predicates.file_is_minified_$bool, predicates.file_is_flattened_$bool];
  if (!readiness.every(Boolean)) throw new Error(`Comprehension target is not ready: ${JSON.stringify(predicates, null, 2)}`);

  const instance = JSON.parse(JSON.stringify(task));
  instance.verify_target_array.filename = projectionRelativePath;
  fs.mkdirSync(roomPath, { recursive: true });
  removeActiveInstances();
  writeJson(activePathFor(sha), instance);
  console.log(`[comprehension-task] instantiated ${TASK_ID} for ${projectionRelativePath}`);
}

async function verify(instanceRelativePath, evaluationCommitSha) {
  const evaluationSha = validateCommitSha(evaluationCommitSha);
  const absoluteInstance = resolveRepoFile(instanceRelativePath);
  if (!fs.existsSync(absoluteInstance)) throw new Error(`Task instance not found: ${instanceRelativePath}`);

  const instance = readJson(absoluteInstance);
  const target = instance?.verify_target_array?.filename;
  const predicates = filePredicates(target);
  const ready = predicates.file_does_exist_$bool && predicates.file_is_json_$bool && predicates.file_is_minified_$bool && predicates.file_is_flattened_$bool;
  let pass = ready;
  let expectedSignatures = null;
  let expectedCount = null;
  let archiveFilename = null;
  let failure = null;

  try {
    if (!ready) throw new Error('Target-array readiness truth table did not evaluate to AND=true.');
    expectedSignatures = expectedNonemptySignatures(predicates.parsed);
    expectedCount = expectedSignatures.length;

    if (JSON.stringify(instance?.doRecord_withReturnSchema?.semantic_evaluations) !== JSON.stringify(EXPECTED_EVALS)) {
      throw new Error('semantic_evaluations does not match the required evaluation contract.');
    }
    if (instance?.count_array_nonempty_items?.filename !== '$verify_target_array.filename') throw new Error('count_array_nonempty_items.filename no longer points to verify_target_array.filename.');
    if (instance?.count_array_nonempty_items?.how_many !== expectedCount) throw new Error(`how_many must equal ${expectedCount}.`);
    if (instance?.doRecord_withReturnSchema?.original_array_filename !== '$verify_target_array.filename') throw new Error('original_array_filename no longer points to verify_target_array.filename.');
    if (instance?.doRecord_withReturnSchema?.nonempty_items_counted !== expectedCount) throw new Error(`nonempty_items_counted must equal ${expectedCount}.`);
    if (instance?.doRecord_withReturnSchema?.returnSchemaArraySize !== expectedCount) throw new Error(`returnSchemaArraySize must equal ${expectedCount}.`);

    const batches = instance?.doRecord_withReturnSchema?.batch_archive_filenames;
    if (!Array.isArray(batches) || (expectedCount > 0 && batches.length === 0)) throw new Error('batch_archive_filenames must record the generated batch archives.');

    archiveFilename = instance?.combine_and_send_batch_archives?.complete_batch_archive_filename;
    if (typeof archiveFilename !== 'string' || archiveFilename.trim() === '' || archiveFilename === 'not_yet_combined') throw new Error('complete_batch_archive_filename has not been completed.');

    const records = parseJsonArchive(archiveFilename);
    if (!validateSemanticEvaluationArray(records, expectedSignatures)) {
      throw new Error('Complete archive does not contain exactly one literal-signature keyed record with all six required semantic evaluations, in source order, for every non-empty source signature.');
    }
  } catch (error) {
    pass = false;
    failure = error.message;
  }

  fs.rmSync(absoluteInstance, { force: true });

  if (pass) {
    writeJson(resultPathFor(evaluationSha, 'PASS'), {
      status: 'PASS',
      task: TASK_ID,
      source_filename: target,
      nonempty_items_counted: expectedCount,
      semantic_evaluations: EXPECTED_EVALS,
      complete_batch_archive_filename: archiveFilename
    });
    console.log(`[comprehension-task] PASS ${evaluationSha}`);
    return true;
  }

  writeJson(resultPathFor(evaluationSha, 'FAILED'), {
    status: 'FAILED',
    task: TASK_ID,
    reason: failure || 'Task completion verification failed.'
  });
  console.log(`[comprehension-task] FAILED ${evaluationSha}: ${failure || 'verification failed'}`);
  return false;
}

async function main() {
  const mode = process.argv[2];
  if (mode === 'issue') return issue(process.argv[3]);
  if (mode === 'verify') {
    const ok = await verify(process.argv[3], process.argv[4]);
    process.exitCode = ok ? 0 : 2;
    return;
  }
  throw new Error('Usage: comprehension-task-reading-room.js issue <commit-sha> | verify <task-instance-path> <evaluation-commit-sha>');
}

main().catch(error => {
  console.error(error.stack || error.message || String(error));
  process.exitCode = 1;
});

/**
 * Config-driven evaluator runtime. In generic mode it loads arbitrary labeled
 * inputs, an evaluation heuristic, and an output schema from config.json.
 * Supervisor-specific Agents/source evaluation remains available in non-generic mode.
 */
const fs = require('node:fs');
const path = require('node:path');

const configPath = path.join(__dirname, 'config.json');
const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));

const runtimeRoot = path.resolve(__dirname, config.runtime_root || '.');
const evaluationRoot = runtimeRoot;
const isGenericMode = config.evaluation_mode === 'generic';

function optionalPath(base, configuredPath) {
  return typeof configuredPath === 'string' && configuredPath.trim() ? path.resolve(base, configuredPath) : null;
}

const supervisorRoot = !isGenericMode ? optionalPath(evaluationRoot, config.supervisor_root) : null;
const agentsPath = !isGenericMode && supervisorRoot ? optionalPath(supervisorRoot, config.agents_file) : null;
const programPath = !isGenericMode && supervisorRoot ? optionalPath(supervisorRoot, config.program_file) : null;
const step3EvaluationPath = !isGenericMode && supervisorRoot ? optionalPath(supervisorRoot, config.artifact_target_file) : null;
const nextPath = path.join(evaluationRoot, config.new_message_folder, config.new_message_file);
const supervisorMessagesPath = path.join(evaluationRoot, config.messages_file);
const genericMessagesPath = optionalPath(evaluationRoot, config.generic_messages_file);
const messagesPath = isGenericMode ? (genericMessagesPath || supervisorMessagesPath) : supervisorMessagesPath;
const evaluationOutputPath = path.join(evaluationRoot, config.evaluation_output_file);
const revisionDeliverablesOutputPath = optionalPath(evaluationRoot, config.revision_deliverables_output_path);
const revisionAgentsOutputPath = revisionDeliverablesOutputPath ? optionalPath(revisionDeliverablesOutputPath, config.revision_agents_output_file) : null;
const revisionProgramOutputPath = revisionDeliverablesOutputPath ? optionalPath(revisionDeliverablesOutputPath, config.revision_program_output_file) : null;
const sourceRevisionEnabled = !isGenericMode && config.source_revision_enabled === true;
const sourceRevisionConfigOutputPath = !isGenericMode ? optionalPath(evaluationRoot, config.source_revision_config_output_path) : null;
const artifactRevisionEnabled = !isGenericMode && config.artifact_revision_enabled === true;
const artifactRevisionOutputPath = !isGenericMode ? optionalPath(evaluationRoot, config.artifact_revision_output_path) : null;
const artifactRevisionPreservePointers = Array.isArray(config.artifact_revision_preserve_json_pointers)
  ? config.artifact_revision_preserve_json_pointers
  : [];

const apiKey = process.env.GEMINI_API_KEY;
const model = process.env.GEMINI_MODEL || config.default_model;
const requestTimeoutMs = Number(config.request_timeout_ms || 180000);

const readText = filePath => fs.readFileSync(filePath, 'utf8');
const readJson = filePath => JSON.parse(readText(filePath));

function ensureParent(filePath) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
}

function writeJson(filePath, value) {
  ensureParent(filePath);
  fs.writeFileSync(filePath, JSON.stringify(value, null, 2) + '\n');
}

function numbered(text) {
  return text
    .split(/\r?\n/)
    .map((line, index) => `${String(index + 1).padStart(5, ' ')} | ${line}`)
    .join('\n');
}

function extractJson(text) {
  const trimmed = text.trim();
  try {
    return JSON.parse(trimmed);
  } catch (directError) {
    const outerFence = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
    if (!outerFence) throw directError;
    return JSON.parse(outerFence[1].trim());
  }
}

function normalizeTextFile(text) {
  return text.trimEnd() + '\n';
}

function normalizeRevisedProgram(program) {
  const trimmed = program.trim();
  const fenced = trimmed.match(/^```(?:javascript|js)?\s*([\s\S]*?)\s*```$/i);
  return normalizeTextFile(fenced ? fenced[1] : program);
}

function normalizeRevisedAgents(agents) {
  const trimmed = agents.trim();
  const fenced = trimmed.match(/^```(?:markdown|md)?\s*([\s\S]*?)\s*```$/i);
  return normalizeTextFile(fenced ? fenced[1] : agents);
}

function appendNextMessage(messages, nextmessage) {
  if (!Array.isArray(messages.contents)) {
    throw new Error('evaluator-messages.json must contain contents[].');
  }
  if (
    !nextmessage ||
    nextmessage.role !== 'user' ||
    !Array.isArray(nextmessage.parts) ||
    !nextmessage.parts.some(part => typeof part.text === 'string')
  ) {
    throw new Error('The configured next-message file must contain a Gemini user content object with text.');
  }
  const last = messages.contents[messages.contents.length - 1];
  if (JSON.stringify(last) !== JSON.stringify(nextmessage)) messages.contents.push(nextmessage);
  return messages;
}

function loadGenericInputs() {
  const descriptors = Array.isArray(config.generic_inputs) ? config.generic_inputs : [];
  return descriptors.map((input, index) => {
    if (!input || typeof input !== 'object') {
      throw new Error(`generic_inputs[${index}] must be an object.`);
    }
    const key = typeof input.key === 'string' && input.key.trim() ? input.key.trim() : `input_${index + 1}`;
    const type = input.type || 'file';
    if (type === 'literal') {
      return { key, type, source: 'config.literal', content: String(input.value ?? '') };
    }
    if (type === 'file') {
      if (typeof input.path !== 'string' || input.path.trim() === '') {
        throw new Error(`generic_inputs[${index}] file input requires path.`);
      }
      const absolutePath = path.resolve(evaluationRoot, input.path);
      return { key, type, source: absolutePath, content: readText(absolutePath) };
    }
    throw new Error(`Unsupported generic input type: ${type}`);
  });
}

function buildGenericEvaluationInstruction(genericInputs) {
  if (typeof config.evaluation_heuristic !== 'string' || config.evaluation_heuristic.trim() === '') {
    throw new Error('Generic evaluation requires non-empty config.evaluation_heuristic.');
  }

  if (!config.evaluation_output_schema || Array.isArray(config.evaluation_output_schema) || typeof config.evaluation_output_schema !== 'object') {
    throw new Error('Generic evaluation requires config.evaluation_output_schema object.');
  }

  const sections = [
    'You are an independent generic evaluator. The runtime supplies labeled inputs without assigning semantics to them.',
    'The evaluation heuristic is supplied by config and is authoritative for how the inputs are interpreted.',
    'Use only the supplied inputs and the configured heuristic. Do not silently import assumptions from the normal GeminiSupervisor Agents/source evaluation mode.',
    'Return one JSON object matching this schema:',
    JSON.stringify(config.evaluation_output_schema, null, 2),
    'Configured evaluation heuristic:',
    config.evaluation_heuristic,
    'Configured inputs:'
  ];

  for (const input of genericInputs) {
    sections.push(`===== INPUT: ${input.key} | source: ${input.source} =====`, input.content);
  }

  return sections.join('\n\n');
}

function decodePointerToken(token) {
  return token.replace(/~1/g, '/').replace(/~0/g, '~');
}

function valueAtJsonPointer(value, pointer) {
  if (pointer === '') return value;
  if (typeof pointer !== 'string' || !pointer.startsWith('/')) {
    throw new Error(`Invalid JSON pointer: ${pointer}`);
  }
  return pointer
    .slice(1)
    .split('/')
    .map(decodePointerToken)
    .reduce((current, token) => {
      if (current === null || current === undefined || !Object.prototype.hasOwnProperty.call(Object(current), token)) {
        throw new Error(`JSON pointer does not resolve: ${pointer}`);
      }
      return current[token];
    }, value);
}

function assertPreservedPointers(original, revised) {
  for (const pointer of artifactRevisionPreservePointers) {
    const before = valueAtJsonPointer(original, pointer);
    const after = valueAtJsonPointer(revised, pointer);
    if (JSON.stringify(before) !== JSON.stringify(after)) {
      throw new Error(`Artifact revision changed preserved JSON pointer ${pointer}.`);
    }
  }
}

function buildSystemInstruction(agents, program, step3Evaluation) {
  const evaluationSchema = {
    response_type: 'evaluation',
    evaluation_basis: {
      agents_md: 'authoritative',
      program: 'implementation_under_test',
      step3_evaluation: 'merged_heuristic_and_question_corpus'
    },
    overall_result: 'PASS | FAIL | INDETERMINATE',
    executive_summary: 'string',
    requirement_evaluations: [
      {
        requirement_id: 'string',
        agents_md_reference: { lines: 'string', requirement: 'string' },
        program_reference: { lines: 'string | null', behavior: 'string' },
        result: 'PASS | FAIL | PARTIAL | NOT_APPLICABLE | INDETERMINATE',
        explanation: 'string',
        required_change: 'string | null'
      }
    ],
    transition_evaluation: {
      exact_transition_key: 'string',
      expected_values: ['PASS', 'FAIL'],
      execution_to_supervisor_handoff: 'PASS | FAIL | PARTIAL | INDETERMINATE',
      missing_key_repair_branch: 'PASS | FAIL | PARTIAL | INDETERMINATE',
      fail_restarts_same_execution_step: 'PASS | FAIL | PARTIAL | INDETERMINATE',
      pass_advances_procedure: 'PASS | FAIL | PARTIAL | INDETERMINATE',
      explanation: 'string'
    },
    unauthorized_or_invented_control_logic: [
      { program_lines: 'string', behavior: 'string', conflict_with_agents_md: 'string' }
    ],
    omissions: [
      { agents_md_lines: 'string', missing_behavior: 'string', consequence: 'string' }
    ],
    recommended_changes: [
      { priority: 'REQUIRED | OPTIONAL', change: 'string', reason: 'string' }
    ]
  };

  const pairedRevisionSchema = {
    response_type: 'paired_revision',
    revision_basis: {
      agents_md: 'specification_being_revised',
      prior_evaluator_context: 'used',
      current_program: 'implementation_being_revised',
      source_config: 'shared_external_reference_configuration',
      step3_evaluation: 'merged_heuristic_and_question_corpus'
    },
    corrections_applied: [
      {
        issue: 'string',
        agents_change: 'string',
        program_change: 'string',
        source_config_change: 'string',
        rationale: 'string'
      }
    ],
    unresolved_requirements: ['string'],
    revised_agents_md: '<complete, non-truncated contents of Agents.md>',
    revised_program: '<complete, non-truncated contents of send-to-gemini.js>',
    revised_source_config: '<complete JSON object for ChatMachines/GeminiSupervisor/config.json>'
  };

  const artifactRevisionSchema = {
    response_type: 'artifact_revision',
    revision_basis: {
      target_file: config.artifact_target_file,
      output_path: config.artifact_revision_output_path,
      preserve_json_pointers: artifactRevisionPreservePointers
    },
    corrections_applied: [
      {
        issue: 'string',
        change: 'string',
        rationale: 'string'
      }
    ],
    unresolved_requirements: ['string'],
    revised_artifact: '<complete, non-truncated JSON value for the configured artifact>'
  };

  const sections = [
    'You are the independent Gemini Supervisor evaluator/reviser.',
    'Agents.md is the authoritative and self-contained source for procedure rules, evaluation definitions, and pass/fail criteria.',
    'The merged Step 3 evaluation JSON supplied below is the single Step3_TSR evaluation source. Use its evaluation_heuristic object as the U/P or expectation-vs-outcome evaluation method and use step3_tsr.tests as the complete Step 3 question corpus.',
    'Do not require evaluator-definitions.md or evaluation-tests.md. Do not require, invent, or restore evaluation_documents_read or any equivalent field whose purpose is tracking evaluation-definition reads.',
    'The latest user message in the evaluator conversation controls whether you evaluate, produce a paired revision, or revise the configured artifact.',
    'Agents.md and send-to-gemini.js are a paired specification/runtime surface. When the latest request changes their shared behavior or dependencies, revise both together in one paired_revision response.',
    'When a paired revision introduces or changes references to files outside Agents.md and send-to-gemini.js, create one shared Supervisor source config and make both revised files point to that same config/key rather than independently hardcoding divergent external paths.',
    'Use prior evaluator conversation messages as historical context, but re-check them against CURRENT configured inputs. Historical requirements superseded by the current canonical contract must not be reintroduced.',
    'Evaluate or revise actual content, not comments about content.',
    'Preserve the intended procedure, per-step return schemas, branches, loops, supervisory gates, run isolation, persistence, and user-request semantics. Do not invent substitute control logic.',
    'The per-step return schema is the central communication/control surface for that step. A step does not communicate completion, advancement, or a valid execution result outside its required return schema.',
    'return_schema_completed refers only to completion of the governing step return schema, never completion of the whole multi-step procedure.',
    'Transitions are driven by supervisory_gate.gate_result. FAIL repeats the same execution step; PASS advances exactly one step after persistence/checkpoint; missing or malformed supervisory transition data is repaired only on the supervisory side.',
    'If the latest user message asks for an evaluation, return only one JSON object matching this evaluation schema:',
    JSON.stringify(evaluationSchema, null, 2),
    'If the latest user message asks to revise Agents.md and source code together, return only one JSON object matching this paired revision schema:',
    JSON.stringify(pairedRevisionSchema, null, 2),
    'For a paired revision, revised_agents_md MUST contain the entire replacement Agents.md, revised_program MUST contain the entire replacement send-to-gemini.js, and revised_source_config MUST contain the complete shared Supervisor config JSON object. Do not truncate, use ellipses, omit unchanged sections, or provide patches.',
    'For a paired revision, Agents.md and send-to-gemini.js must agree on the shared config contract. Any external file dependency represented in that config must use the same config key and resolved path semantics in both revised files.'
  ];

  if (artifactRevisionEnabled) {
    sections.push(
      `Artifact revision is enabled. The source artifact is ${step3EvaluationPath}.`,
      `Write the revised file deliverable to the configured output path ${artifactRevisionOutputPath}.`,
      `These JSON pointers are immutable and must be reproduced exactly: ${JSON.stringify(artifactRevisionPreservePointers)}.`,
      'If the latest user message asks to revise the configured artifact, return only one JSON object matching this artifact revision schema:',
      JSON.stringify(artifactRevisionSchema, null, 2),
      'For artifact_revision, revised_artifact MUST contain the entire revised JSON artifact. Do not return a patch, Markdown fence, ellipsis, omitted unchanged content, or commentary outside the JSON object.'
    );
  }

  sections.push(
    'Apply every correction required by the latest user message. If anything remains impossible without inventing an unspecified external interface, list it in unresolved_requirements.',
    'Use the provided line numbers when citing source evidence in evaluation/correction metadata.',
    '',
    '===== CURRENT AGENTS.MD =====',
    numbered(agents),
    '',
    '===== CURRENT SEND-TO-GEMINI.JS =====',
    numbered(program),
    '',
    '===== MERGED STEP 3 EVALUATION JSON =====',
    JSON.stringify(step3Evaluation, null, 2)
  );

  return sections.join('\n\n');
}

async function callGemini(messages, systemInstruction) {
  const response = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-goog-api-key': apiKey
      },
      body: JSON.stringify({
        system_instruction: { parts: [{ text: systemInstruction }] },
        contents: messages.contents,
        generationConfig: { responseMimeType: 'application/json' }
      }),
      signal: AbortSignal.timeout(requestTimeoutMs)
    }
  );

  const text = await response.text();
  let body;
  try {
    body = JSON.parse(text);
  } catch (_) {
    throw new Error(`Gemini returned non-JSON HTTP ${response.status}: ${text}`);
  }
  if (!response.ok) {
    throw new Error(`Gemini HTTP ${response.status}: ${JSON.stringify(body.error || body)}`);
  }

  const reply = body.candidates?.[0]?.content;
  if (reply?.role !== 'model' || !Array.isArray(reply.parts) || reply.parts.length === 0) {
    throw new Error(`Gemini returned no evaluator content: ${JSON.stringify(body)}`);
  }

  const replyText = reply.parts.map(part => part.text || '').join('\n').trim();
  return { reply, payload: extractJson(replyText) };
}

async function main() {
  if (!apiKey) throw new Error('GEMINI_API_KEY is missing from the GitHub Actions environment.');

  const useGenericEvaluation = isGenericMode;
  const triggerEnvelope = readJson(nextPath);
  const nextMessage = triggerEnvelope.nextmessage;
  const rawRunNonce = triggerEnvelope.run_nonce;
  if (typeof rawRunNonce !== 'string' || rawRunNonce.trim() === '') {
    throw new Error('The configured next-message file must contain non-empty run_nonce.');
  }
  const runNonce = rawRunNonce.trim();
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(runNonce)) {
    throw new Error(`Invalid run_nonce ${runNonce}. Use only letters, digits, dot, underscore, and hyphen.`);
  }
  const evaluationsRootPath = optionalPath(evaluationRoot, config.evaluations_root || 'evaluations');
  if (!evaluationsRootPath) throw new Error('evaluations_root is required.');
  const runRootPath = path.join(evaluationsRootPath, runNonce);
  const runEvaluationOutputPath = path.join(runRootPath, config.run_evaluation_file || 'evaluation.json');
  const runMessagesPath = path.join(runRootPath, config.run_messages_file || 'messages.json');
  const runOutputsPath = path.join(runRootPath, config.run_outputs_directory || 'outputs');
  const runRevisionAgentsOutputPath = path.join(runOutputsPath, config.revision_agents_output_file || 'revised-Agents.md');
  const runRevisionProgramOutputPath = path.join(runOutputsPath, config.revision_program_output_file || 'revised-send-to-gemini.js');
  const runSourceConfigOutputPath = path.join(runOutputsPath, path.basename(config.source_revision_config_output_path || 'config.json'));
  const runArtifactRevisionOutputPath = path.join(runOutputsPath, config.artifact_revision_output_file || path.basename(config.artifact_revision_output_path || 'step-3-evaluation.json'));
  const writeLatestCompatibilityOutputs = config.write_latest_compatibility_outputs !== false;
  const reuseGenericHistory = config.generic_reuse_message_history === true;
  const initialMessages = useGenericEvaluation && !reuseGenericHistory
    ? { contents: [] }
    : (fs.existsSync(messagesPath) ? readJson(messagesPath) : { contents: [] });
  const messages = appendNextMessage(initialMessages, nextMessage);
  let agents = null;
  let program = null;
  let step3Evaluation = null;
  let genericInputs = [];
  let systemInstruction;

  if (useGenericEvaluation) {
    genericInputs = loadGenericInputs();
    systemInstruction = buildGenericEvaluationInstruction(genericInputs);
  } else {
    agents = readText(agentsPath);
    program = readText(programPath);
    step3Evaluation = readJson(step3EvaluationPath);
    systemInstruction = buildSystemInstruction(agents, program, step3Evaluation);
  }

  const result = await callGemini(messages, systemInstruction);

  if (useGenericEvaluation) {
    const expectedResponseType = config.evaluation_output_schema?.response_type;
    if (typeof expectedResponseType === 'string' && expectedResponseType && result.payload.response_type !== expectedResponseType) {
      throw new Error(`Generic evaluator returned response_type ${result.payload.response_type ?? 'missing'}; expected ${expectedResponseType}.`);
    }
  }

  messages.contents.push(result.reply);
  writeJson(runMessagesPath, messages);
  if (writeLatestCompatibilityOutputs) writeJson(messagesPath, messages);

  if (!useGenericEvaluation && result.payload.response_type === 'paired_revision') {
    if (!sourceRevisionEnabled) {
      throw new Error('Paired revision response received while source_revision_enabled is false.');
    }
    if (typeof result.payload.revised_agents_md !== 'string' || result.payload.revised_agents_md.trim() === '') {
      throw new Error('Paired revision did not contain complete revised_agents_md.');
    }
    if (typeof result.payload.revised_program !== 'string' || result.payload.revised_program.trim() === '') {
      throw new Error('Paired revision did not contain complete revised_program.');
    }
    if (!Object.prototype.hasOwnProperty.call(result.payload, 'revised_source_config')) {
      throw new Error('Paired revision did not contain complete revised_source_config.');
    }
    const revisedSourceConfig = typeof result.payload.revised_source_config === 'string'
      ? extractJson(result.payload.revised_source_config)
      : result.payload.revised_source_config;
    if (!revisedSourceConfig || Array.isArray(revisedSourceConfig) || typeof revisedSourceConfig !== 'object') {
      throw new Error('revised_source_config must be a JSON object.');
    }
    fs.mkdirSync(runOutputsPath, { recursive: true });
    fs.writeFileSync(runRevisionAgentsOutputPath, normalizeRevisedAgents(result.payload.revised_agents_md));
    fs.writeFileSync(runRevisionProgramOutputPath, normalizeRevisedProgram(result.payload.revised_program));
    writeJson(runSourceConfigOutputPath, revisedSourceConfig);
    if (writeLatestCompatibilityOutputs) {
      fs.mkdirSync(revisionDeliverablesOutputPath, { recursive: true });
      fs.writeFileSync(revisionAgentsOutputPath, normalizeRevisedAgents(result.payload.revised_agents_md));
      fs.writeFileSync(revisionProgramOutputPath, normalizeRevisedProgram(result.payload.revised_program));
      writeJson(sourceRevisionConfigOutputPath, revisedSourceConfig);
    }
  }

  if (!useGenericEvaluation && result.payload.response_type === 'artifact_revision') {
    if (!artifactRevisionEnabled) {
      throw new Error('Artifact revision response received while artifact_revision_enabled is false.');
    }
    if (!Object.prototype.hasOwnProperty.call(result.payload, 'revised_artifact')) {
      throw new Error('Artifact revision did not contain complete revised_artifact.');
    }
    const revisedArtifact = typeof result.payload.revised_artifact === 'string'
      ? extractJson(result.payload.revised_artifact)
      : result.payload.revised_artifact;
    assertPreservedPointers(step3Evaluation, revisedArtifact);
    writeJson(runArtifactRevisionOutputPath, revisedArtifact);
    if (writeLatestCompatibilityOutputs) writeJson(artifactRevisionOutputPath, revisedArtifact);
  }

  writeJson(runEvaluationOutputPath, result.payload);
  if (writeLatestCompatibilityOutputs) writeJson(evaluationOutputPath, result.payload);

  console.log(JSON.stringify({
    runtime: 'Node.js',
    node_version: process.version,
    config: configPath,
    runtime_root: runtimeRoot,
    run_nonce: runNonce,
    run_root: runRootPath,
    model,
    trigger: nextPath,
    message_stream: runMessagesPath,
    evaluated_program: useGenericEvaluation ? null : programPath,
    specification: useGenericEvaluation ? null : agentsPath,
    evaluation_mode: config.evaluation_mode || 'supervisor',
    generic_inputs: genericInputs.map(input => ({ key: input.key, source: input.source })),
    evaluation_heuristic_configured: typeof config.evaluation_heuristic === 'string' && config.evaluation_heuristic.trim() !== '',
    step3_evaluation: useGenericEvaluation ? null : step3EvaluationPath,
    output: runEvaluationOutputPath,
    outputs_directory: runOutputsPath,
    latest_compatibility_output: writeLatestCompatibilityOutputs ? evaluationOutputPath : null,
    response_type: result.payload.response_type ?? null,
    revision_agents_output: result.payload.response_type === 'paired_revision' ? runRevisionAgentsOutputPath : null,
    revision_program_output: result.payload.response_type === 'paired_revision' ? runRevisionProgramOutputPath : null,
    revision_source_config_output: result.payload.response_type === 'paired_revision' ? runSourceConfigOutputPath : null,
    artifact_revision_output: result.payload.response_type === 'artifact_revision' ? runArtifactRevisionOutputPath : null
  }, null, 2));
}

main().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

'use strict';

const fs = require('node:fs');
const path = require('node:path');
const runtime = require('../../hierarchical-runtime/audit.js');

const repoRoot = path.resolve(process.cwd());
const evalRoot = 'ChatMachines/GeminiEvaluation/evaluations/stage1_current_feature_inventory_20261002_1';
const configPath = path.join(repoRoot, evalRoot, 'config.json');
const analysisPath = path.join(repoRoot, 'ChatMachines/TokenizerCalibration/stage1-corpus-analysis.json');
const batchesRoot = path.join(repoRoot, 'ChatMachines/TokenizerCalibration/stage1-batches');
const outputRoot = path.join(repoRoot, evalRoot, 'execution');
const model = 'gemini-3.8-flash';
const charsPerToken = 3.9;
const baseDividerMaxTokens = 12000;

const temporaryCompactTaskSuffix = ' Return a compact consolidation. The complete serialized response must remain below 6000 estimated tokens under Math.ceil(characters / 3.9). Prefer merging overlapping records over retaining near-duplicates. Keep names concise, descriptions to one or two sentences, mechanic_summary values to one concise sentence, and include only evidence necessary to preserve distinct implementation support.';
const temporaryCompactCriteriaSuffix = '\n5. Compactness: The complete serialized response must remain below 6000 estimated tokens using Math.ceil(characters / 3.9); remove redundant wording and redundant evidence while preserving distinct source support.';

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function writeJson(file, value) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify(value, null, 2) + '\n');
}

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function approximateTokens(value) {
  let text = '';
  if (typeof value === 'string') text = value;
  else if (value !== null && value !== undefined) text = JSON.stringify(value);
  return text ? Math.ceil(text.length / charsPerToken) : 0;
}

function parseJsonWithRepairs(text) {
  const attempts = [];
  const trimmed = String(text || '').trim();
  if (!trimmed) return null;
  attempts.push(trimmed);
  attempts.push(trimmed.replace(/\\(?!["\\/bfnrtu])/g, '\\\\'));

  for (const candidate of [...attempts]) {
    attempts.push(candidate.replace(/,\s*([}\]])/g, '$1'));
  }

  const seen = new Set();
  for (const candidate of attempts) {
    if (seen.has(candidate)) continue;
    seen.add(candidate);
    try {
      const parsed = JSON.parse(candidate);
      if (parsed && typeof parsed === 'object') return parsed;
    } catch {}
  }
  return null;
}

function recoverRequiredFields({rawResponse}) {
  if (typeof rawResponse !== 'string') return null;
  const text = rawResponse.trim();
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fence) {
    const parsed = parseJsonWithRepairs(fence[1]);
    if (parsed) return parsed;
  }

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    return parseJsonWithRepairs(text.slice(firstBrace, lastBrace + 1));
  }
  return null;
}

function stripTemporaryCompactness(evaluator) {
  if (!evaluator) return;
  if (typeof evaluator.task === 'string' && evaluator.task.endsWith(temporaryCompactTaskSuffix)) {
    evaluator.task = evaluator.task.slice(0, -temporaryCompactTaskSuffix.length);
  }
  if (typeof evaluator.criteria === 'string' && evaluator.criteria.endsWith(temporaryCompactCriteriaSuffix)) {
    evaluator.criteria = evaluator.criteria.slice(0, -temporaryCompactCriteriaSuffix.length);
  }
}

function removeResponseTokenConditions(acceptance) {
  if (!acceptance || !Array.isArray(acceptance.conditions)) return;
  acceptance.conditions = acceptance.conditions.filter(condition => condition?.source !== 'response.tokens');
}

function updateConfig(config) {
  config.token_counter = {
    implementation: 'linear_chars_divisor',
    characters_per_token: charsPerToken,
    formula: 'Math.ceil(text.length / 3.9)'
  };

  config.stage1_round_policy = {
    b0: {
      divider_max_tokens: baseDividerMaxTokens,
      response_limit: 'response.tokens < divider.max_tokens / 2',
      division_source: 'precomputed Gemini countTokens batches'
    },
    consolidation: {
      applies_when: 'B > 0',
      divider_max_tokens_formula: '12000 * (2 ** B)',
      response_limit_formula: 'floor(round_input_tokens / assigned_b_count)',
      purpose: 'allow canonical feature lists to grow as batches are recombined while preventing aggregate round expansion'
    },
    terminal_round: {
      response_token_limit: null,
      note: 'terminal round is exempt from the consolidation response ceiling'
    }
  };

  for (const rule of config.B_rules || []) {
    const evaluator = rule?.iterator?.evaluator;
    if (!evaluator) continue;
    evaluator.model = model;

    if (rule?.when?.B?.gt === 0) {
      stripTemporaryCompactness(evaluator);
      removeResponseTokenConditions(rule.iterator.acceptance);
      rule.iterator.divider.base_max_tokens = baseDividerMaxTokens;
      rule.iterator.divider.max_tokens_formula = '12000 * (2 ** B)';
      rule.iterator.acceptance.dynamic_response_limit = {
        ordinary_round: 'floor(round_input_tokens / assigned_b_count)',
        terminal_round: null
      };
    }
  }

  return config;
}

function scaledIteratorForB(B, config) {
  const iterator = clone(runtime.resolveIteratorForB(B, config));
  if (B > 0) {
    iterator.divider.max_tokens = baseDividerMaxTokens * (2 ** B);
  }
  return iterator;
}

function iteratorForAssignedRound({state, baseIterator, roundInputTokens, assignedBatchCount}) {
  const iterator = clone(baseIterator);

  if (state.B === 0) return iterator;

  removeResponseTokenConditions(iterator.acceptance);

  if (state.terminalRound === true) {
    iterator.acceptance.effective_response_token_limit = null;
    iterator.acceptance.response_limit_reason = 'terminal_round_exempt';
    return iterator;
  }

  if (!Number.isInteger(assignedBatchCount) || assignedBatchCount < 1) {
    throw new Error(`Invalid assigned batch count for B${state.B}: ${assignedBatchCount}`);
  }

  const responseLimit = Math.floor(roundInputTokens / assignedBatchCount);
  iterator.acceptance.conditions.push({
    id: 'response_not_exceeding_round_input_share',
    source: 'response.tokens',
    operator: 'lte',
    value: responseLimit
  });
  iterator.acceptance.effective_response_token_limit = responseLimit;
  iterator.acceptance.response_limit_reason = 'floor(round_input_tokens / assigned_b_count)';
  return iterator;
}

function loadSuccessfulB0Checkpoints(expectedB0) {
  const checkpoints = new Map();
  for (const entry of expectedB0) {
    const file = path.join(outputRoot, 'B0', `b${entry.b}.json`);
    if (!fs.existsSync(file)) continue;
    try {
      const result = readJson(file);
      if (result?.B === 0 && result?.b === entry.b && result?.status === 'success' && result?.response !== null && result?.response !== undefined) {
        checkpoints.set(entry.b, result);
      }
    } catch {}
  }
  return checkpoints;
}

function persistBatchResult(B, b, result) {
  const dir = path.join(outputRoot, `B${B}`);
  fs.mkdirSync(dir, { recursive: true });
  writeJson(path.join(dir, `b${b}.json`), result);
}

function persistRound(round, aggregate, metadata) {
  const dir = path.join(outputRoot, `B${round.B}`);
  fs.mkdirSync(dir, { recursive: true });
  writeJson(path.join(dir, 'round.json'), {
    B: round.B,
    status: round.status,
    assignedBatchCount: round.assignedBatchCount,
    roundInputTokens: metadata.roundInputTokens,
    dividerMaxTokens: metadata.dividerMaxTokens,
    responseTokenLimit: metadata.responseTokenLimit,
    terminalRoundOnEntry: metadata.terminalRoundOnEntry,
    aggregateResponseTokens: round.aggregateResponseTokens,
    batches: round.batches,
    aggregate
  });
}

function persistState(state, finalReturn = null) {
  writeJson(path.join(outputRoot, 'runtime-state.json'), state);
  if (finalReturn !== null) writeJson(path.join(outputRoot, 'final.json'), finalReturn);
}

async function processRound({state, config, dependencies, batches, iterator, roundInputTokens, checkpointResults = null}) {
  const round = runtime.createRoundState({ B: state.B, batches, iterator });
  const metadata = {
    roundInputTokens,
    dividerMaxTokens: iterator.divider.max_tokens,
    responseTokenLimit: iterator.acceptance?.effective_response_token_limit ?? null,
    terminalRoundOnEntry: state.terminalRound === true
  };
  state.b = 0;

  while (state.b < batches.length) {
    const batch = batches[state.b];
    let result = checkpointResults?.get(state.b) || null;

    if (result) {
      result = clone(result);
      result.id = `B${state.B}-b${state.b}`;
      result.B = state.B;
      result.b = state.b;
      result.assignedContextTokens = batch.assignedContextTokens;
      result.provenance = batch.provenance || [];
      result.checkpointReused = true;
    } else {
      result = await runtime.processBatch({
        B: state.B,
        b: state.b,
        batch,
        iterator,
        config,
        gemini: null,
        dependencies
      });
    }

    runtime.commitBatchResult({ round, batchResult: result });
    runtime.updateSupervisoryState({ runtimeState: state, batchResult: result });
    persistBatchResult(state.B, state.b, result);

    if (runtime.evaluateFailedBatchStopCondition({ runtimeState: state, iterator, config })) {
      state.status = 'failed_b_stop';
      round.status = 'failed_b_stop';
      state.rounds.push(round);
      const finalReturn = runtime.assembleProgramReturn({
        reason: 'failed_b_stop',
        runtimeState: state,
        round,
        aggregate: null,
        config
      });
      persistRound(round, null, metadata);
      persistState(state, finalReturn);
      return { terminal: true, finalReturn };
    }
    state.b += 1;
  }

  const aggregate = await runtime.aggregateSuccessfulBatchResults({
    round,
    config,
    dependencies,
    gemini: null
  });
  round.status = 'complete';
  state.rounds.push(round);
  persistRound(round, aggregate, metadata);

  if (state.terminalRound === true) {
    state.status = 'complete';
    const finalReturn = runtime.assembleProgramReturn({
      reason: 'terminal_round_complete',
      runtimeState: state,
      round,
      aggregate,
      config
    });
    persistState(state, finalReturn);
    return { terminal: true, finalReturn };
  }

  if (runtime.evaluateTerminationCondition({ aggregate, iterator, runtimeState: state, config })) {
    state.terminalRound = true;
  }

  state.currentContext = aggregate.context;
  state.B += 1;
  persistState(state);
  return { terminal: false, aggregate };
}

async function main() {
  if (!process.env.GEMINI_API_KEY) throw new Error('GEMINI_API_KEY is missing.');

  const config = updateConfig(readJson(configPath));
  const analysis = readJson(analysisPath);
  const expectedB0 = analysis?.B0?.batches || [];
  if (!expectedB0.length) throw new Error('No pre-divided B0 batches were found in stage1-corpus-analysis.json.');

  const b0Checkpoints = loadSuccessfulB0Checkpoints(expectedB0);

  fs.rmSync(outputRoot, { recursive: true, force: true });
  fs.mkdirSync(outputRoot, { recursive: true });
  writeJson(configPath, config);

  const dependencies = {
    countTokens: value => approximateTokens(value),
    recoverRequiredFields
  };

  const state = runtime.createRuntimeState(null);
  const b0Batches = expectedB0.map(entry => {
    const file = path.join(batchesRoot, `B0-b${entry.b}.json`);
    if (!fs.existsSync(file)) throw new Error(`Missing pre-divided B0 batch: ${file}`);
    return {
      id: `B0-b${entry.b}`,
      B: 0,
      b: entry.b,
      context: readJson(file),
      assignedContextTokens: entry.tokens,
      provenance: [`predivided:B0-b${entry.b}`]
    };
  });

  const b0Iterator = scaledIteratorForB(0, config);
  const b0RoundInputTokens = expectedB0.reduce((sum, entry) => sum + Number(entry.tokens || 0), 0);
  let result = await processRound({
    state,
    config,
    dependencies,
    batches: b0Batches,
    iterator: b0Iterator,
    roundInputTokens: b0RoundInputTokens,
    checkpointResults: b0Checkpoints
  });
  if (result.terminal) {
    console.log(JSON.stringify(result.finalReturn, null, 2));
    return;
  }

  while (true) {
    const roundInputTokens = approximateTokens(state.currentContext);
    const divisionIterator = scaledIteratorForB(state.B, config);
    const batches = await runtime.divideContextIntoBatches({
      context: state.currentContext,
      divider: divisionIterator.divider,
      config,
      dependencies,
      gemini: null,
      B: state.B
    });
    const iterator = iteratorForAssignedRound({
      state,
      baseIterator: divisionIterator,
      roundInputTokens,
      assignedBatchCount: batches.length
    });

    result = await processRound({
      state,
      config,
      dependencies,
      batches,
      iterator,
      roundInputTokens
    });
    if (result.terminal) {
      console.log(JSON.stringify(result.finalReturn, null, 2));
      return;
    }
  }
}

main().catch(error => {
