};

console.log(JSON.stringify(result, null, 2));

#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const reportRoot = __dirname;
const RESERVED_CHARS = 16384;
const PADDING_CHARACTER = '~';

function walk(dir) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const absolute = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(absolute));
    else if (entry.isFile()) out.push(absolute);
  }
  return out;
}

function parseMetadataLine(text, relativePath) {
  const newlineIndex = text.indexOf('\n');
  const firstLine = (newlineIndex < 0 ? text : text.slice(0, newlineIndex)).replace(/\r$/, '');

  let parsed;
  try {
    parsed = JSON.parse(firstLine);
  } catch (error) {
    throw new Error(`First line of ${relativePath} must be metadata JSON: ${error.message}`);
  }

  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error(`Metadata in ${relativePath} must be a JSON object.`);
  }

  const metadata = (
    parsed.metadata &&
    typeof parsed.metadata === 'object' &&
    !Array.isArray(parsed.metadata) &&
    parsed.this === undefined
  ) ? parsed.metadata : parsed;

  if (metadata.this !== 'metadata') {
    throw new Error(`this must equal "metadata" in ${relativePath}.`);
  }

  return { metadata, newlineIndex };
}

function extractBody(text, metadata, newlineIndex) {
  const region = metadata.metadata_region;
  if (
    region &&
    typeof region === 'object' &&
    !Array.isArray(region) &&
    Number.isInteger(region.body_start) &&
    region.body_start >= 0 &&
    text.length >= region.body_start
  ) {
    return text.slice(region.body_start);
  }

  if (newlineIndex < 0) return '';

  let body = text.slice(newlineIndex + 1);
  if (body.startsWith('\r\n')) body = body.slice(2);
  else if (body.startsWith('\n')) body = body.slice(1);
  return body;
}

function buildReservedDocument(metadata, body, relativePath) {
  metadata.metadata_region = {
    length: RESERVED_CHARS,
    padding_character: PADDING_CHARACTER,
    body_start: RESERVED_CHARS,
    coordinate_unit: 'UTF-16_code_unit'
  };

  const metadataLine = JSON.stringify(metadata);
  const paddingCount = RESERVED_CHARS - metadataLine.length - 2;
  if (paddingCount < 0) {
    throw new Error(`Metadata in ${relativePath} exceeds the ${RESERVED_CHARS}-character reserved region.`);
  }

  const reserved = `${metadataLine}\n${PADDING_CHARACTER.repeat(paddingCount)}\n`;
  if (reserved.length !== RESERVED_CHARS) {
    throw new Error(`Reserved metadata region length mismatch in ${relativePath}.`);
  }

  return reserved + body;
}

function main() {
  const textFiles = walk(reportRoot)
    .filter(file => file.toLowerCase().endsWith('.txt'))
    .sort();

  let changed = 0;
  for (const file of textFiles) {
    const relativePath = path.relative(reportRoot, file).split(path.sep).join('/');
    const text = fs.readFileSync(file, 'utf8');
    const { metadata, newlineIndex } = parseMetadataLine(text, relativePath);
    const body = extractBody(text, metadata, newlineIndex);
    const next = buildReservedDocument(metadata, body, relativePath);

    if (next !== text) {
      fs.writeFileSync(file, next, 'utf8');
      changed += 1;
    }
  }

  console.log(`Reserved ${RESERVED_CHARS} metadata characters with ${JSON.stringify(PADDING_CHARACTER)} padding in ${changed} document(s).`);
}

main();

#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const YAML = require('yaml');

const reportRoot = __dirname;
const repoRoot = path.resolve(reportRoot, '../../..');
const defaultConfigPath = path.join(reportRoot, 'configurable-updates.yml');

function isInside(parent, child) {
  const relative = path.relative(parent, child);
  return relative === '' || (!relative.startsWith(`..${path.sep}`) && relative !== '..' && !path.isAbsolute(relative));
}

function loadConfig(configPath) {
  const parsed = YAML.parse(fs.readFileSync(configPath, 'utf8'));
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('Configuration must be a YAML object.');
  }
  if (parsed.version !== 1) {
    throw new Error('Configuration version must equal 1.');
  }
  if (!Array.isArray(parsed.lists)) {
    throw new Error('Configuration lists must be an array.');
  }
  return parsed;
}

async function main() {
  const requestedConfig = process.argv[2]
    ? path.resolve(repoRoot, process.argv[2])
    : defaultConfigPath;

  if (!isInside(reportRoot, requestedConfig)) {
    throw new Error('Configuration file must be inside the SBE report root.');
  }
  if (!fs.existsSync(requestedConfig)) {
    throw new Error(`Configuration file not found: ${requestedConfig}`);
  }

  const config = loadConfig(requestedConfig);

  for (let listIndex = 0; listIndex < config.lists.length; listIndex++) {
    const list = config.lists[listIndex];
    if (!list || typeof list !== 'object' || Array.isArray(list)) {
      throw new Error(`lists[${listIndex}] must be an object.`);
    }
    if (typeof list.name !== 'string' || list.name.trim() === '') {
      throw new Error(`lists[${listIndex}].name must be a non-empty string.`);
    }
    if (typeof list.script !== 'string' || list.script.trim() === '') {
      throw new Error(`lists[${listIndex}].script must be a non-empty string.`);
    }
    if (!Array.isArray(list.args)) {
      throw new Error(`lists[${listIndex}].args must be an array of positional-argument arrays.`);
    }

    const scriptPath = path.resolve(reportRoot, list.script);
    if (!isInside(reportRoot, scriptPath)) {
      throw new Error(`${list.name}: script must be inside the SBE report root.`);
    }
    if (path.extname(scriptPath).toLowerCase() !== '.js') {
      throw new Error(`${list.name}: script must be a .js file.`);
    }
    if (!fs.existsSync(scriptPath)) {
      throw new Error(`${list.name}: script not found: ${list.script}`);
    }

    delete require.cache[require.resolve(scriptPath)];
    const handler = require(scriptPath);
    if (typeof handler !== 'function') {
      throw new Error(`${list.name}: ${list.script} must export one function.`);
    }

    for (let argIndex = 0; argIndex < list.args.length; argIndex++) {
      const args = list.args[argIndex];
      if (!Array.isArray(args)) {
        throw new Error(`${list.name}.args[${argIndex}] must be an array of positional arguments.`);
      }
      console.log(`${list.name}[${argIndex}] -> ${list.script}(${args.length} arg(s))`);
      await handler(...args);
    }
  }

  console.log(`Completed ${config.lists.length} configured list(s).`);
}

main().catch(error => {
  console.error(error.stack || error.message || String(error));
  process.exitCode = 1;
});

#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

const reportRoot = __dirname;
const repoRoot = path.resolve(reportRoot, '../../..');
const manifestPath = path.join(reportRoot, 'MANIFEST.json');

function walk(dir) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const absolute = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(absolute));
    else if (entry.isFile()) out.push(absolute);
  }
  return out;
}

function toPosix(value) {
  return value.split(path.sep).join('/');
}

function readEmbeddedMetadata(file) {
  const text = fs.readFileSync(file, 'utf8');
  const relative = toPosix(path.relative(reportRoot, file));
  const firstNewline = text.indexOf('\n');

  if (firstNewline < 0) {
    throw new Error(`Missing embedded metadata JSON line in ${relative}.`);
  }

  let parsed;
  try {
    parsed = JSON.parse(text.slice(0, firstNewline).replace(/\r$/, ''));
  } catch (error) {
    throw new Error(`First line of ${relative} must be the embedded metadata JSON object: ${error.message}`);
  }

  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error(`Embedded metadata in ${relative} must be a JSON object.`);
  }

  // Transitional compatibility: accept the former {"metadata": {...}} envelope,
  // but the canonical on-disk format is now the metadata object itself.
  const metadata = (
    parsed.metadata &&
    typeof parsed.metadata === 'object' &&
    !Array.isArray(parsed.metadata) &&
    parsed.this === undefined
  ) ? parsed.metadata : parsed;

  if (metadata.this !== 'metadata') {
    throw new Error(`Embedded metadata in ${relative} must contain this = "metadata".`);
  }
  if (typeof metadata.file_description !== 'string' || metadata.file_description.trim() === '') {
    throw new Error(`Embedded metadata in ${relative} must contain a non-empty file_description.`);
  }

  const region = metadata.metadata_region;
  if (!region || typeof region !== 'object' || Array.isArray(region)) {
    throw new Error(`Embedded metadata in ${relative} must contain metadata_region.`);
  }
  if (!Number.isInteger(region.length) || region.length <= 2) {
    throw new Error(`metadata_region.length must be an integer greater than 2 in ${relative}.`);
  }
  if (region.body_start !== region.length) {
    throw new Error(`metadata_region.body_start must equal metadata_region.length in ${relative}.`);
  }
  if (typeof region.padding_character !== 'string' || region.padding_character.length !== 1 || /\s/.test(region.padding_character)) {
    throw new Error(`metadata_region.padding_character must be one non-whitespace character in ${relative}.`);
  }
  if (region.coordinate_unit !== 'UTF-16_code_unit') {
    throw new Error(`metadata_region.coordinate_unit must equal "UTF-16_code_unit" in ${relative}.`);
  }
  if (text.length < region.body_start) {
    throw new Error(`${relative} is shorter than metadata_region.body_start.`);
  }

  const paddingStart = firstNewline + 1;
  const paddingEnd = region.body_start - 1;
  if (paddingEnd < paddingStart || text[paddingEnd] !== '\n') {
    throw new Error(`Reserved metadata region terminator is invalid in ${relative}.`);
  }
  const padding = text.slice(paddingStart, paddingEnd);
  if (padding !== region.padding_character.repeat(padding.length)) {
    throw new Error(`Reserved metadata padding is invalid in ${relative}.`);
  }

  return metadata;
}

function lastCommitFor(absolutePath) {
  const repoRelative = toPosix(path.relative(repoRoot, absolutePath));
  const sha = execFileSync('git', ['-C', repoRoot, 'log', '-1', '--format=%H', '--', repoRelative], {
    encoding: 'utf8'
  }).trim();
  if (!/^[0-9a-f]{40}$/i.test(sha)) {
    throw new Error(`Could not resolve last commit for ${repoRelative}.`);
  }
  return sha;
}

function main() {
  const textFiles = walk(reportRoot)
    .filter(file => file.toLowerCase().endsWith('.txt'))
    .sort((a, b) => toPosix(path.relative(reportRoot, a)).localeCompare(toPosix(path.relative(reportRoot, b))));

  const documents = textFiles.map(file => {
    const relative = toPosix(path.relative(reportRoot, file));
    const metadata = readEmbeddedMetadata(file);
    const dirname = path.posix.dirname(relative);

    return {
      filename: path.posix.basename(relative),
      folder_structure: dirname === '.' ? [] : dirname.split('/'),
      file_description: metadata.file_description.trim(),
      last_commit: lastCommitFor(file)
    };
  });

  const manifest = {
    metadata: {
      this: 'metadata',
      manifest_description: 'Generated manifest of text documents in the SBE report root and its subdirectories.',
      report_root: toPosix(path.relative(repoRoot, reportRoot)),
      file_description_source: 'embedded text-file JSON -> file_description',
      embedded_metadata_contract: '{"this":"metadata","file_description":"...","metadata_region":{"length":N,"padding_character":"<one non-whitespace character>","body_start":N,"coordinate_unit":"UTF-16_code_unit"}}'
    },
    documents
  };

  fs.writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`, 'utf8');
  console.log(`Wrote ${documents.length} document records to ${manifestPath}.`);
}

main();

#!/usr/bin/env node

const fs = require('node:fs');
const path = require('node:path');

function getChildInfo(value) {
  if (value === null || typeof value !== 'object') {
    return { count: 0, type: 'primitive' };
  }
  if (Array.isArray(value)) {
    return { count: value.length, type: 'array' };
  }
  return { count: Object.keys(value).length, type: 'object' };
}

function formatPath(basePath, segment, isIndex = false) {
  if (isIndex) {
    return basePath ? `${basePath}[${segment}]` : `[${segment}]`;
  }
  const safeIdentifier = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
  if (safeIdentifier.test(segment)) {
    return basePath ? `${basePath}.${segment}` : segment;
  }
  return basePath ? `${basePath}[${JSON.stringify(segment)}]` : `[${JSON.stringify(segment)}]`;
}

function checkItem(node, currentPath, topLevelIndex, violations) {
  if (node === null || typeof node !== 'object') {
    return;
  }

  if (Array.isArray(node)) {
    for (let i = 0; i < node.length; i++) {
      const element = node[i];
      const elementPath = formatPath(currentPath, i, true);
      checkItem(element, elementPath, topLevelIndex, violations);
    }
    return;
  }

  for (const key of Object.keys(node)) {
    const value = node[key];
    const keyPath = formatPath(currentPath, key, false);
    const childInfo = getChildInfo(value);

    if (childInfo.count > 1) {
      violations.push({
        top_level_index: topLevelIndex,
        path: keyPath,
        child_count: childInfo.count,
        value_type: childInfo.type
      });
    }

    if (value !== null && typeof value === 'object') {
      checkItem(value, keyPath, topLevelIndex, violations);
    }
  }
}

function main() {
  const args = process.argv.slice(2);
  if (args.length === 0) {
    console.error(JSON.stringify({
      error: 'Missing required file path argument.',
      usage: 'node check-single-child.js <path-to-json-file>'
    }, null, 2));
    process.exit(2);
  }

  const inputPath = path.resolve(args[0]);
  if (!fs.existsSync(inputPath)) {
    console.error(JSON.stringify({
      error: `File not found: ${inputPath}`
    }, null, 2));
    process.exit(2);
  }

  let raw;
  try {
    raw = fs.readFileSync(inputPath, 'utf8');
  } catch (err) {
    console.error(JSON.stringify({
      error: `Failed to read file: ${err.message}`
    }, null, 2));
    process.exit(2);
  }

  let data;
  try {
    data = JSON.parse(raw);
  } catch (err) {
    console.error(JSON.stringify({
      error: `Failed to parse JSON: ${err.message}`
    }, null, 2));
    process.exit(2);
  }

  if (!Array.isArray(data)) {
    console.error(JSON.stringify({
      error: 'Top-level JSON value must be an array.'
    }, null, 2));
    process.exit(2);
  }

  const violations = [];
  for (let i = 0; i < data.length; i++) {
    checkItem(data[i], '', i, violations);
  }

  const result = {
    file: inputPath,
    total_top_level_items: data.length,
    valid: violations.length === 0,
    violation_count: violations.length,
    violations
  };

  console.log(JSON.stringify(result, null, 2));

  if (violations.length > 0) {
    process.exit(1);
  }
}

main();

'use strict';

const fs = require('node:fs');

const inputPath = 'ChatMachines/TokenizerCalibration/agents-by-header.json';
const outputPath = 'ChatMachines/TokenizerCalibration/agents-by-header-flattened.json';

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function isContainer(value) {
  return Array.isArray(value) || isObject(value);
}

function decomposeObjectMembers(objectValue, wrap, atoms) {
  const keys = Object.keys(objectValue);
  if (keys.length === 0) {
    atoms.push(wrap({}));
    return;
  }

  for (const key of keys) {
    const child = objectValue[key];

    if (isObject(child)) {
      atoms.push(wrap({ [key]: {} }));
      if (Object.keys(child).length > 0) {
        decomposeObjectMembers(child, value => wrap({ [key]: value }), atoms);
      }
      continue;
    }

    if (Array.isArray(child)) {
      atoms.push(wrap({ [key]: [] }));
      if (child.length > 0) {
        decomposeArrayMembers(child, value => wrap({ [key]: value }), atoms);
      }
      continue;
    }

    atoms.push(wrap({ [key]: child }));
  }
}

function decomposeArrayMembers(arrayValue, wrap, atoms) {
  for (const member of arrayValue) {
    if (isObject(member)) {
      if (Object.keys(member).length === 0) {
        atoms.push(wrap([{}]));
      } else {
        decomposeObjectMembers(member, value => wrap([value]), atoms);
      }
      continue;
    }

    if (Array.isArray(member)) {
      if (member.length === 0) {
        atoms.push(wrap([[]]));
      } else {
        decomposeArrayMembers(member, value => wrap([value]), atoms);
      }
      continue;
    }

    atoms.push(wrap([member]));
  }
}

function flattenAtomicProjection(source) {
  const atoms = [];
  const identity = value => value;

  if (isObject(source)) {
    atoms.push({});
    decomposeObjectMembers(source, identity, atoms);
    return atoms;
  }

  if (Array.isArray(source)) {
    atoms.push([]);
    decomposeArrayMembers(source, identity, atoms);
    return atoms;
  }

  return [source];
}

function main() {
  const source = JSON.parse(fs.readFileSync(inputPath, 'utf8'));
  const flattened = flattenAtomicProjection(source);
  fs.writeFileSync(outputPath, JSON.stringify(flattened) + '\n', 'utf8');
  console.log(JSON.stringify({ input: inputPath, output: outputPath, atoms: flattened.length }));
}

if (require.main === module) main();

module.exports = { flattenAtomicProjection };

'use strict';

const fs = require('node:fs');
const path = require('node:path');

const model = process.env.GEMINI_MODEL || 'gemini-3.8-flash';
const agentsPath = 'ChatMachines/GeminiSupervisor/Agents.md';
const agentsHeaderJsonPath = 'ChatMachines/TokenizerCalibration/agents-by-header.json';
const agentsRoundTripPath = 'ChatMachines/TokenizerCalibration/agents-by-header-roundtrip.json';
const resultsPath = 'ChatMachines/TokenizerCalibration/tokenizer-results.json';

function agentsJsonByHeader(markdown) {
  const lines = markdown.split(/\r?\n/);
  const sections = [];
  let currentHeader = 'Agents.md';

  for (let i = 0; i < lines.length; i += 1) {
    const header = lines[i].match(/^#{1,6}\s+(.+?)\s*$/);
    if (header) {
      currentHeader = header[1];
      continue;
    }

    if (lines[i].trim() !== '```json') continue;

    const jsonLines = [];
    i += 1;
    while (i < lines.length && lines[i].trim() !== '```') {
      jsonLines.push(lines[i]);
      i += 1;
    }

    const jsonText = jsonLines.join('\n').trim();
    if (!jsonText) continue;

    let parsed;
    try {
      parsed = JSON.parse(jsonText);
    } catch (error) {
      throw new Error(`Invalid JSON under header "${currentHeader}": ${error.message}`);
    }

    sections.push({ [currentHeader]: parsed });
  }

  return sections;
}

async function exactCount(text) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:countTokens`;
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'x-goog-api-key': process.env.GEMINI_API_KEY,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      contents: [{ parts: [{ text }] }]
    })
  });

  if (!response.ok) {
    throw new Error(`countTokens ${response.status}: ${await response.text()}`);
  }

  const result = await response.json();
  return result.totalTokens;
}

async function measure(file) {
  const text = fs.readFileSync(file, 'utf8');
  const characters = text.length;
  const exactTokens = await exactCount(text);
  const div3 = Math.ceil(characters / 3);
  const div4 = Math.ceil(characters / 4);

  return {
    file,
    characters,
    exact_tokens: exactTokens,
    characters_per_token: Number((characters / exactTokens).toFixed(4)),
    ceil_chars_div_3: div3,
    div_3_error_tokens: div3 - exactTokens,
    div_3_error_percent: Number((((div3 - exactTokens) / exactTokens) * 100).toFixed(2)),
    ceil_chars_div_4: div4,
    div_4_error_tokens: div4 - exactTokens,
    div_4_error_percent: Number((((div4 - exactTokens) / exactTokens) * 100).toFixed(2))
  };
}

async function main() {
  const rawAgents = fs.readFileSync(agentsPath, 'utf8');
  const headerJson = agentsJsonByHeader(rawAgents);

  fs.mkdirSync(path.dirname(agentsHeaderJsonPath), { recursive: true });
  fs.writeFileSync(agentsHeaderJsonPath, JSON.stringify(headerJson) + '\n');

  const headerJsonText = fs.readFileSync(agentsHeaderJsonPath, 'utf8');
  const roundTripText = JSON.stringify(JSON.parse(headerJsonText));
  fs.writeFileSync(agentsRoundTripPath, roundTripText);

  const samples = [
    agentsPath,
    agentsHeaderJsonPath,
    agentsRoundTripPath,
    'ChatMachines/GeminiSupervisor/send-to-gemini.js',
    'ChatMachines/GeminiSupervisor/tests/step-3-evaluation.json'
  ];

  const results = [];
  for (const file of samples) results.push(await measure(file));

  const raw = results.find(item => item.file === agentsPath);
  const structured = results.find(item => item.file === agentsHeaderJsonPath);
  const roundTrip = results.find(item => item.file === agentsRoundTripPath);

  const output = {
    generated_at: new Date().toISOString(),
    model,
    agents_header_json: {
      sections: headerJson.length,
      raw_tokens: raw.exact_tokens,
      structured_tokens: structured.exact_tokens,
      token_change: structured.exact_tokens - raw.exact_tokens,
      token_change_percent: Number((((structured.exact_tokens - raw.exact_tokens) / raw.exact_tokens) * 100).toFixed(2))
    },
    exact_json_stringify_parse: {
      expression: 'JSON.stringify(JSON.parse(text))',
      input_file: agentsHeaderJsonPath,
      output_file: agentsRoundTripPath,
      input_characters: structured.characters,
      output_characters: roundTrip.characters,
      character_change: roundTrip.characters - structured.characters,
      input_tokens: structured.exact_tokens,
      output_tokens: roundTrip.exact_tokens,
      token_change: roundTrip.exact_tokens - structured.exact_tokens,
      token_change_percent: Number((((roundTrip.exact_tokens - structured.exact_tokens) / structured.exact_tokens) * 100).toFixed(4))
    },
    samples: results
  };

  fs.writeFileSync(resultsPath, JSON.stringify(output, null, 2) + '\n');
  console.log(JSON.stringify(output, null, 2));
}

main().catch(error => {
  console.error(error.stack || error.message || String(error));
  process.exit(1);
});

